function countCommasInRange(low, high) {
    const countUpTo = (n) => {
        let commas = 0n;
        let threshold = 1000n;
        const bn = BigInt(n);
        while (bn >= threshold) {
            commas += (bn - threshold + 1n);
            threshold *= 1000n;
        }
        return commas;
    };
    return Number(countUpTo(high) - countUpTo(low - 1));
